313→    /// Create a new directory.
314→    pub fn handle_mkdir(
315→        fs: &mut CipherBoxFS,
316→        parent: u64,
317→        name: &OsStr,
318→        reply: ReplyEntry,
319→    ) {
320→        let name_str = match name.to_str() {
321→            Some(n) => n,
322→            None => {
323→                reply.error(libc::EINVAL);
324→                return;
325→            }
326→        };
327→
328→        if is_platform_special(name_str) {
329→            reply.error(libc::EACCES);
330→            return;
331→        }
332→
333→        let parent_exists = fs.inodes.get(parent).map(|inode| {
334→            matches!(inode.kind, InodeKind::Root { .. } | InodeKind::Folder { .. })
335→        });
336→        if parent_exists != Some(true) {
337→            reply.error(libc::ENOENT);
338→            return;
339→        }
340→
341→        log::debug!("mkdir: {} in parent {}", name_str, parent);
342→
343→        let result = (|| -> Result<fuser::FileAttr, String> {
344→            let folder_key = crate::crypto::utils::generate_file_key();
345→
346→            let (ipns_public_key, ipns_private_key) =
347→                crate::crypto::ed25519::generate_ed25519_keypair();
348→
349→            let ipns_pub_arr: [u8; 32] = ipns_public_key.clone().try_into()
350→                .map_err(|_| "Invalid IPNS public key length".to_string())?;
351→            let ipns_name = crate::crypto::ipns::derive_ipns_name(&ipns_pub_arr)
352→                .map_err(|e| format!("Failed to derive IPNS name: {}", e))?;
353→
354→            let wrapped_folder_key = crate::crypto::ecies::wrap_key(
355→                &folder_key, &fs.public_key,
356→            )
357→            .map_err(|e| format!("Folder key wrapping failed: {}", e))?;
358→            let encrypted_folder_key_hex = hex::encode(&wrapped_folder_key);
359→
360→            let ino = fs.inodes.allocate_ino();
361→            let now = SystemTime::now();
362→
363→            let attr = FileAttrs {
364→                ino,
365→                size: 0,
366→                blocks: 0,
367→                atime: now,
368→                mtime: now,
369→                ctime: now,
370→                crtime: now,
371→                is_dir: true,
372→                perm: 0o755,
373→                nlink: 2,
374→            };
375→            let fuse_attr = attr.to_fuse_attr(current_uid(), current_gid());
376→
377→            let inode = InodeData {
378→                ino,
379→                parent_ino: parent,
380→                name: name_str.to_string(),
381→                kind: InodeKind::Folder {
382→                    ipns_name: ipns_name.clone(),
383→                    encrypted_folder_key: encrypted_folder_key_hex,
384→                    folder_key: zeroize::Zeroizing::new(folder_key.to_vec()),
385→                    ipns_private_key: Some(zeroize::Zeroizing::new(ipns_private_key.clone())),
386→                    children_loaded: true,
387→                },
388→                attr,
389→                children: Some(vec![]),
390→                write_generation: 0,
391→            };
392→
393→            fs.inodes.insert(inode);
394→
395→            if let Some(parent_inode) = fs.inodes.get_mut(parent) {
396→                if let Some(ref mut children) = parent_inode.children {
397→                    children.push(ino);
398→                }
399→                parent_inode.attr.mtime = SystemTime::now();
400→                parent_inode.attr.ctime = SystemTime::now();
401→            }
402→
403→            let metadata = crate::crypto::folder::FolderMetadata {
404→                version: "v2".to_string(),
405→                children: vec![],
406→            };
407→
408→            let json_bytes = crate::fuse::encrypt_metadata_to_json(
409→                &metadata, &folder_key,
410→            )?;
411→
412→            let encrypted_ipns_for_tee = if let Some(ref tee_key) = fs.tee_public_key {
413→                let wrapped = crate::crypto::ecies::wrap_key(&ipns_private_key, tee_key)
414→                    .map_err(|e| format!("TEE key wrapping failed: {}", e))?;
415→                Some(hex::encode(&wrapped))
416→            } else {
417→                None
418→            };
419→            let tee_key_epoch = fs.tee_key_epoch;
420→
421→            let (parent_metadata, parent_folder_key, parent_ipns_key, parent_ipns_name, parent_old_cid) =
422→                fs.build_folder_metadata(parent)?;
423→
424→            let api = fs.api.clone();
425→            let rt = fs.rt.clone();
426→            let ipns_name_clone = ipns_name.clone();
427→            let coordinator = fs.publish_coordinator.clone();
428→
429→            std::thread::spawn(move || {
430→                let result = rt.block_on(async {
431→                    let initial_cid = crate::api::ipfs::upload_content(
432→                        &api, &json_bytes,
433→                    ).await?;
434→
435→                    let ipns_key_arr: [u8; 32] = ipns_private_key.try_into()
436→                        .map_err(|_| "Invalid IPNS key length".to_string())?;
437→                    let value = format!("/ipfs/{}", initial_cid);
438→                    let record = crate::crypto::ipns::create_ipns_record(
439→                        &ipns_key_arr, &value, 0, 86_400_000,
440→                    ).map_err(|e| format!("IPNS record creation failed: {}", e))?;
441→                    let marshaled = crate::crypto::ipns::marshal_ipns_record(&record)
442→                        .map_err(|e| format!("IPNS marshal failed: {}", e))?;
443→
444→                    use base64::Engine;
445→                    let record_b64 = base64::engine::general_purpose::STANDARD
446→                        .encode(&marshaled);
447→
448→                    // New folder initial publish: sequence 0, no conflict check needed
449→                    let req = crate::api::ipns::IpnsPublishRequest {
450→                        ipns_name: ipns_name_clone.clone(),
451→                        record: record_b64,
452→                        metadata_cid: initial_cid,
453→                        encrypted_ipns_private_key: encrypted_ipns_for_tee,
454→                        key_epoch: tee_key_epoch,
455→                        expected_sequence_number: None,
456→                    };
457→                    match crate::api::ipns::publish_ipns(&api, &req).await? {
458→                        crate::api::ipns::PublishResult::Success => {
459→                            coordinator.record_publish(&ipns_name_clone, 0);
460→                            log::info!("New folder IPNS published: {}", ipns_name_clone);
461→                        }
462→                        crate::api::ipns::PublishResult::Conflict { .. } => {
463→                            // Sequence 0 should never conflict -- log and continue
464→                            log::warn!("Unexpected conflict on new folder IPNS publish for {}", ipns_name_clone);
465→                        }
466→                    }
467→
468→                    let lock = coordinator.get_lock(&parent_ipns_name);
469→                    let _guard = lock.lock().await;
470→
471→                    let parent_json = crate::fuse::encrypt_metadata_to_json(
472→                        &parent_metadata, &parent_folder_key,
473→                    )?;
474→
475→                    let seq = coordinator.resolve_sequence(&api, &parent_ipns_name).await?;
476→
477→                    let parent_meta_cid = crate::api::ipfs::upload_content(
478→                        &api, &parent_json,
479→                    ).await?;
480→
481→                    let parent_key_arr: [u8; 32] = parent_ipns_key.try_into()
482→                        .map_err(|_| "Invalid parent IPNS key length".to_string())?;
483→                    let new_seq = seq + 1;
484→                    let parent_value = format!("/ipfs/{}", parent_meta_cid);
485→                    let parent_record = crate::crypto::ipns::create_ipns_record(
486→                        &parent_key_arr, &parent_value, new_seq, 86_400_000,
487→                    ).map_err(|e| format!("Parent IPNS record failed: {}", e))?;
488→                    let parent_marshaled = crate::crypto::ipns::marshal_ipns_record(
489→                        &parent_record,
490→                    ).map_err(|e| format!("Parent IPNS marshal failed: {}", e))?;
491→                    let parent_record_b64 = base64::engine::general_purpose::STANDARD
492→                        .encode(&parent_marshaled);
493→
494→                    // Parent folder publish after mkdir includes conflict detection.
495→                    // On conflict, log a warning -- the debounced publish queue will
496→                    // retry the parent metadata on the next cycle.
497→                    // TODO: Add full re-fetch+merge+retry for parent mkdir publish (v2).
498→                    let parent_req = crate::api::ipns::IpnsPublishRequest {
499→                        ipns_name: parent_ipns_name.clone(),
500→                        record: parent_record_b64,
501→                        metadata_cid: parent_meta_cid,
502→                        encrypted_ipns_private_key: None,
503→                        key_epoch: None,
504→                        expected_sequence_number: Some(seq.to_string()),
505→                    };
506→                    match crate::api::ipns::publish_ipns(&api, &parent_req).await? {
507→                        crate::api::ipns::PublishResult::Success => {
508→                            coordinator.record_publish(&parent_ipns_name, new_seq);
509→                            // Only unpin old CID on successful publish
510→                            if let Some(old) = parent_old_cid {
511→                                let _ = crate::api::ipfs::unpin_content(&api, &old).await;
512→                            }
513→                            log::info!("Parent metadata published after mkdir");
514→                        }
515→                        crate::api::ipns::PublishResult::Conflict { current_sequence_number } => {
516→                            log::warn!(
517→                                "Conflict on parent publish after mkdir (expected seq {}, server has {}). \
518→                                Debounced publish will retry.",
519→                                seq, current_sequence_number
520→                            );
521→                            // Do not record_publish or unpin -- let the next debounced publish pick up fresh seq
522→                        }
523→                    }
524→                    Ok::<(), String>(())
525→                });
526→
527→                if let Err(e) = result {
528→                    log::error!("Background mkdir publish failed: {}", e);
529→                }
530→            });
531→
532→            Ok(fuse_attr)
533→        })();
534→
535→        match result {
536→            Ok(fuse_attr) => {
537→                reply.entry(&DIR_TTL, &fuse_attr, 0);
538→            }
539→            Err(e) => {
540→                log::error!("mkdir failed: {}", e);
541→                reply.error(libc::EIO);
542→            }
543→        }
544→    }
