546→    /// Remove an empty directory.
547→    pub fn handle_rmdir(
548→        fs: &mut CipherBoxFS,
549→        parent: u64,
550→        name: &OsStr,
551→        reply: ReplyEmpty,
552→    ) {
553→        let name_str = match name.to_str() {
554→            Some(n) => n,
555→            None => {
556→                reply.error(libc::ENOENT);
557→                return;
558→            }
559→        };
560→
561→        let child_ino = match fs.inodes.find_child(parent, name_str) {
562→            Some(ino) => ino,
563→            None => {
564→                reply.error(libc::ENOENT);
565→                return;
566→            }
567→        };
568→
569→        let cid_to_unpin = match fs.inodes.get(child_ino) {
570→            Some(inode) => {
571→                match &inode.kind {
572→                    InodeKind::Folder { ipns_name, .. } => {
573→                        if let Some(ref children) = inode.children {
574→                            if !children.is_empty() {
575→                                reply.error(libc::ENOTEMPTY);
576→                                return;
577→                            }
578→                        }
579→                        fs.metadata_cache.get(ipns_name)
580→                            .map(|cached| cached.cid.clone())
581→                    }
582→                    _ => {
583→                        reply.error(libc::ENOTDIR);
584→                        return;
585→                    }
586→                }
587→            }
588→            None => {
589→                reply.error(libc::ENOENT);
590→                return;
591→            }
592→        };
593→
594→        log::debug!("rmdir: {} from parent {}", name_str, parent);
595→
596→        fs.inodes.remove(child_ino);
597→
598→        if let Some(parent_inode) = fs.inodes.get_mut(parent) {
599→            parent_inode.attr.mtime = SystemTime::now();
600→            parent_inode.attr.ctime = SystemTime::now();
601→        }
602→
603→        if let Err(e) = fs.update_folder_metadata(parent) {
604→            log::error!("Failed to update folder metadata after rmdir: {}", e);
605→        }
606→
607→        if let Some(cid) = cid_to_unpin {
608→            let api = fs.api.clone();
609→            fs.rt.spawn(async move {
610→                if let Err(e) = crate::api::ipfs::unpin_content(&api, &cid).await {
611→                    log::debug!("Background unpin failed for {}: {}", cid, e);
612→                }
613→            });
614→        }
615→
616→        reply.ok();
617→    }
