619→    /// Rename or move a file/folder.
620→    pub fn handle_rename(
621→        fs: &mut CipherBoxFS,
622→        parent: u64,
623→        name: &OsStr,
624→        newparent: u64,
625→        newname: &OsStr,
626→        reply: ReplyEmpty,
627→    ) {
628→        log::debug!(
629→            "rename: {:?} (parent {}) -> {:?} (parent {})",
630→            name, parent, newname, newparent,
631→        );
632→        let name_str = match name.to_str() {
633→            Some(n) => n,
634→            None => {
635→                reply.error(libc::EINVAL);
636→                return;
637→            }
638→        };
639→        let newname_str = match newname.to_str() {
640→            Some(n) => n,
641→            None => {
642→                reply.error(libc::EINVAL);
643→                return;
644→            }
645→        };
646→
647→        // Find source inode (with FUSE-T truncated name fallback)
648→        let (source_ino, actual_name) = match fs.inodes.find_child(parent, name_str) {
649→            Some(ino) => (ino, name_str.to_string()),
650→            None => {
651→                let parent_inode = match fs.inodes.get(parent) {
652→                    Some(i) => i,
653→                    None => {
654→                        reply.error(libc::ENOENT);
655→                        return;
656→                    }
657→                };
658→                let children = parent_inode.children.clone().unwrap_or_default();
659→                let mut matches: Vec<(u64, String)> = Vec::new();
660→                for &child_ino in &children {
661→                    if let Some(child) = fs.inodes.get(child_ino) {
662→                        if is_platform_special(&child.name) {
663→                            continue;
664→                        }
665→                        if child.name.ends_with(name_str) && child.name.len() > name_str.len() {
666→                            matches.push((child_ino, child.name.clone()));
667→                        }
668→                    }
669→                }
670→                if matches.len() == 1 {
671→                    log::debug!(
672→                        "rename suffix-match: truncated {:?} matched full name {:?}",
673→                        name_str, matches[0].1
674→                    );
675→                    (matches[0].0, matches[0].1.clone())
676→                } else {
677→                    log::debug!(
678→                        "rename failed: {:?} not found (suffix matches: {})",
679→                        name_str, matches.len()
680→                    );
681→                    reply.error(libc::ENOENT);
682→                    return;
683→                }
684→            }
685→        };
686→
687→        let name_str = &actual_name;
688→
689→        log::debug!(
690→            "rename: {} (ino {}) in parent {} -> {} in parent {}",
691→            name_str, source_ino, parent, newname_str, newparent,
692→        );
693→
694→        // If destination exists, handle replacement
695→        if let Some(dest_ino) = fs.inodes.find_child(newparent, newname_str) {
696→            // Self-replace (rename "a" to "a" in same dir): no-op
697→            if dest_ino == source_ino {
698→                reply.ok();
699→                return;
700→            }
701→
702→            if let Some(dest_inode) = fs.inodes.get(dest_ino) {
703→                // Validate kind compatibility (POSIX: can't replace file with dir or vice versa)
704→                let source_is_dir = fs.inodes.get(source_ino)
705→                    .map(|i| matches!(i.kind, InodeKind::Root { .. } | InodeKind::Folder { .. }))
706→                    .unwrap_or(false);
707→                let dest_is_dir = matches!(
708→                    dest_inode.kind,
709→                    InodeKind::Root { .. } | InodeKind::Folder { .. }
710→                );
711→                if source_is_dir && !dest_is_dir {
712→                    reply.error(libc::ENOTDIR);
713→                    return;
714→                }
715→                if !source_is_dir && dest_is_dir {
716→                    reply.error(libc::EISDIR);
717→                    return;
718→                }
719→
720→                match &dest_inode.kind {
721→                    InodeKind::Folder { .. } => {
722→                        if let Some(ref children) = dest_inode.children {
723→                            if !children.is_empty() {
724→                                reply.error(libc::ENOTEMPTY);
725→                                return;
726→                            }
727→                        }
728→                    }
729→                    InodeKind::File { cid, .. } => {
730→                        if !cid.is_empty() {
731→                            let cid_clone = cid.clone();
732→                            let api = fs.api.clone();
733→                            fs.rt.spawn(async move {
734→                                let _ = crate::api::ipfs::unpin_content(
735→                                    &api, &cid_clone,
736→                                ).await;
737→                            });
738→                        }
739→                    }
740→                    _ => {}
741→                }
742→            }
743→            fs.inodes.remove(dest_ino);
744→        }
745→
746→        // Remove source from old parent's name index (NFC-normalized)
747→        {
748→            use unicode_normalization::UnicodeNormalization;
749→            let nfc_key: String = name_str.nfc().collect();
750→            fs.inodes.name_to_ino.remove(&(parent, nfc_key));
751→        }
752→
753→        // Update the source inode's name and parent
754→        if let Some(inode) = fs.inodes.get_mut(source_ino) {
755→            inode.name = newname_str.to_string();
756→            inode.parent_ino = newparent;
757→            inode.attr.ctime = SystemTime::now();
758→        }
759→
760→        // Update the name lookup index for the new location (NFC-normalized)
761→        {
762→            use unicode_normalization::UnicodeNormalization;
763→            let nfc_key: String = newname_str.nfc().collect();
764→            fs.inodes.name_to_ino.insert(
765→                (newparent, nfc_key),
766→                source_ino,
767→            );
768→        }
769→
770→        if parent != newparent {
771→            if let Some(old_parent) = fs.inodes.get_mut(parent) {
772→                if let Some(ref mut children) = old_parent.children {
773→                    children.retain(|&c| c != source_ino);
774→                }
775→                old_parent.attr.mtime = SystemTime::now();
776→                old_parent.attr.ctime = SystemTime::now();
777→            }
778→            if let Some(new_parent) = fs.inodes.get_mut(newparent) {
779→                if let Some(ref mut children) = new_parent.children {
780→                    children.push(source_ino);
781→                }
782→                new_parent.attr.mtime = SystemTime::now();
783→                new_parent.attr.ctime = SystemTime::now();
784→            }
785→
786→            if let Err(e) = fs.update_folder_metadata(parent) {
787→                log::error!("Failed to update old parent metadata after rename: {}", e);
788→            }
789→            if let Err(e) = fs.update_folder_metadata(newparent) {
790→                log::error!("Failed to update new parent metadata after rename: {}", e);
791→            }
792→        } else {
793→            if let Some(parent_inode) = fs.inodes.get_mut(parent) {
794→                parent_inode.attr.mtime = SystemTime::now();
795→                parent_inode.attr.ctime = SystemTime::now();
796→            }
797→            if let Err(e) = fs.update_folder_metadata(parent) {
798→                log::error!("Failed to update parent metadata after rename: {}", e);
799→            }
800→        }
801→
802→        reply.ok();
803→    }
804→}
