326→  const handleSelect = useCallback(
327→    (itemId: string, event: { ctrlKey: boolean; shiftKey: boolean; metaKey: boolean }) => {
328→      const isCtrl = event.ctrlKey || event.metaKey;
329→      const isShift = event.shiftKey;
330→
331→      if (isShift && lastSelectedIdRef.current) {
332→        // Range select: select all items between lastSelected and current
333→        // Use sorted children order so the range respects visual order
334→        const sortedChildren = [...children].sort((a, b) => {
335→          if (a.type === 'folder' && b.type !== 'folder') return -1;
336→          if (a.type !== 'folder' && b.type === 'folder') return 1;
337→          return a.name.localeCompare(b.name, undefined, { sensitivity: 'base' });
338→        });
339→
340→        const ids = sortedChildren.map((c) => c.id);
341→        const startIdx = ids.indexOf(lastSelectedIdRef.current);
342→        const endIdx = ids.indexOf(itemId);
343→
344→        if (startIdx !== -1 && endIdx !== -1) {
345→          const rangeStart = Math.min(startIdx, endIdx);
346→          const rangeEnd = Math.max(startIdx, endIdx);
347→          const rangeIds = ids.slice(rangeStart, rangeEnd + 1);
348→
349→          setSelectedIds((prev) => {
350→            const next = new Set(prev);
