475→/// The main filesystem struct.
476→///
477→/// Shared between macOS FUSE and Windows WinFsp implementations.
478→/// Contains the inode table, caches, API client, and all state needed
479→/// for filesystem operations.
480→#[cfg(any(feature = "fuse", feature = "winfsp"))]
481→pub struct CipherBoxFS {
482→    /// Inode table mapping inode numbers to metadata.
483→    pub inodes: inode::InodeTable,
484→    /// Folder metadata cache with 30s TTL.
485→    pub metadata_cache: cache::MetadataCache,
486→    /// File content cache with 256 MiB LRU eviction.
487→    pub content_cache: cache::ContentCache,
488→    /// API client for IPFS/IPNS operations.
489→    pub api: Arc<ApiClient>,
490→    /// User's secp256k1 private key for ECIES decryption (32 bytes).
491→    /// Wrapped in `Zeroizing` for automatic zeroization on drop.
492→    pub private_key: Zeroizing<Vec<u8>>,
493→    /// User's uncompressed secp256k1 public key (65 bytes, 0x04 prefix).
494→    /// Wrapped in `Zeroizing` for automatic zeroization on drop.
495→    pub public_key: Zeroizing<Vec<u8>>,
496→    /// Root folder AES-256 key (32 bytes).
497→    /// Wrapped in `Zeroizing` for automatic zeroization on drop.
498→    pub root_folder_key: Zeroizing<Vec<u8>>,
499→    /// Root IPNS name (k51... format).
500→    pub root_ipns_name: String,
501→    /// Tokio runtime handle for spawning async tasks from filesystem threads.
502→    pub rt: tokio::runtime::Handle,
503→    /// Next file handle counter.
504→    pub next_fh: AtomicU64,
505→    /// Map of open file handles (file_handle::OpenFileHandle for write buffering).
506→    pub open_files: HashMap<u64, file_handle::OpenFileHandle>,
507→    /// Temp directory for write-buffered files.
508→    pub temp_dir: PathBuf,
509→    /// TEE public key hex for encrypting IPNS private keys on new folder creation.
510→    pub tee_public_key: Option<Vec<u8>>,
511→    /// TEE key epoch for encrypting IPNS private keys on new folder creation.
512→    pub tee_key_epoch: Option<u32>,
513→    /// Receiver for background refresh results.
514→    pub refresh_rx: std::sync::mpsc::Receiver<PendingRefresh>,
515→    /// Sender clone for spawning background refreshes.
516→    pub refresh_tx: std::sync::mpsc::Sender<PendingRefresh>,
517→    /// Folders with recent local mutations — skip background refreshes
518→    /// that would overwrite local state before IPNS publish propagates.
519→    /// Maps folder ino -> mutation timestamp.
520→    pub mutated_folders: HashMap<u64, std::time::Instant>,
521→    /// CIDs currently being prefetched in background (to avoid duplicate fetches).
522→    pub prefetching: std::collections::HashSet<String>,
523→    /// Receiver for background content prefetch results.
524→    pub content_rx: std::sync::mpsc::Receiver<PendingContent>,
525→    /// Sender for background content prefetch tasks.
526→    pub content_tx: std::sync::mpsc::Sender<PendingContent>,
527→    /// Plaintext cache for files whose upload is still in flight (keyed by inode).
528→    pub pending_content: HashMap<u64, Vec<u8>>,
529→    /// Receiver for background upload completion notifications.
530→    pub upload_rx: std::sync::mpsc::Receiver<UploadComplete>,
531→    /// Sender for background upload threads to notify completion.
532→    pub upload_tx: std::sync::mpsc::Sender<UploadComplete>,
533→    /// Shared coordinator for IPNS publish sequencing and per-folder locking.
534→    pub publish_coordinator: Arc<PublishCoordinator>,
535→    /// Debounced publish queue: folders needing metadata publish after mutations.
536→    /// Publishes are coalesced and deferred until uploads settle.
537→    publish_queue: HashMap<u64, PublishQueueEntry>,
538→}
