541→impl CipherBoxFS {
542→    /// Get the decrypted folder key for a folder/root inode.
543→    /// Returns None if the inode is not a folder or root.
544→    pub fn get_folder_key(&self, folder_ino: u64) -> Option<Vec<u8>> {
545→        self.inodes.get(folder_ino).and_then(|inode| {
546→            match &inode.kind {
547→                inode::InodeKind::Root { .. } => Some(self.root_folder_key.to_vec()),
548→                inode::InodeKind::Folder { folder_key, .. } => Some(folder_key.to_vec()),
549→                _ => None,
550→            }
551→        })
552→    }
553→
554→    /// Build a FolderMetadata struct from the current inode tree (CPU-only, no network I/O).
555→    /// Returns (metadata, folder_key, ipns_private_key, ipns_name, old_metadata_cid).
556→    pub fn build_folder_metadata(
557→        &self,
558→        folder_ino: u64,
559→    ) -> Result<
560→        (
561→            crate::crypto::folder::FolderMetadata,
562→            Vec<u8>,
563→            Vec<u8>,
564→            String,
565→            Option<String>,
566→        ),
567→        String,
568→    > {
569→        let (folder_key, ipns_private_key, ipns_name, child_inos) = {
570→            let inode = self
571→                .inodes
572→                .get(folder_ino)
573→                .ok_or_else(|| format!("Folder inode {} not found", folder_ino))?;
574→
