async () => {
  // Monkey-patch console to capture all bin-related logging
  const logs = [];
  const origLog = console.log;
  const origWarn = console.warn;
  const origError = console.error;

  console.log = (...args) => {
    const msg = args.map(a => typeof a === 'object' ? JSON.stringify(a) : String(a)).join(' ');
    if (msg.includes('Bin') || msg.includes('bin') || msg.includes('restore') || msg.includes('folder')) {
      logs.push({ level: 'log', msg });
    }
    origLog.apply(console, args);
  };
  console.warn = (...args) => {
    const msg = args.map(a => typeof a === 'object' ? JSON.stringify(a) : String(a)).join(' ');
    logs.push({ level: 'warn', msg });
    origWarn.apply(console, args);
  };
  console.error = (...args) => {
    const msg = args.map(a => typeof a === 'object' ? JSON.stringify(a) : String(a)).join(' ');
    logs.push({ level: 'error', msg });
    origError.apply(console, args);
  };

  window.__binDebugLogs = logs;
  window.__restoreConsole = () => {
    console.log = origLog;
    console.warn = origWarn;
    console.error = origError;
  };

  return 'Console logging patched for bin debug';
}

