                    : 'descending'
                  : 'none'
              }
            >
              {'[SIZE]'}
              {sortIndicator('size')}
            </button>
            <button
              type="button"
              className="bin-column-header bin-column-remaining"
              onClick={() => handleSortClick('daysRemaining')}
              role="columnheader"
              aria-sort={
                sortField === 'daysRemaining'
