```typescript
import { type Page, type Locator } from '@playwright/test';

export class BinPage {
  readonly page: Page;
  readonly binNavItem: Locator;
  readonly emptyBinButton: Locator;
  readonly binList: Locator;
  readonly emptyState: Locator;
  readonly confirmDialog: Locator;
  readonly confirmButton: Locator;
  readonly cancelButton: Locator;

  constructor(page: Page) {
    this.page = page;
    this.binNavItem = page.getByTestId('nav-item-bin');
    this.emptyBinButton = page.getByRole('button', { name: /empty bin/i });
    this.binList = page.locator('.bin-list');
    this.emptyState = page.locator('.bin-empty-state');
    this.confirmDialog = page.locator('[data-testid="confirm-dialog"]');
    this.confirmButton = page.getByRole('button', { name: /confirm|yes|delete/i });
    this.cancelButton = page.getByRole('button', { name: /cancel|no/i });
  }

  async navigate() {
    await this.binNavItem.click();
    await this.page.waitForURL('**/#/bin');
  }

  async getBinItems(): Promise<Locator[]> {
    return this.page.locator('[data-testid^="bin-item-"]').all();
  }

  async getBinItemByName(name: string): Promise<Locator> {
    return this.page.locator(`[data-testid^="bin-item-"]`, { hasText: name });
  }

  async contextMenuAction(itemName: string, action: string) {
    const item = await this.getBinItemByName(itemName);
    await item.click({ button: 'right' });
    await this.page.getByText(action).click();
  }

  async restoreItem(itemName: string) {
    await this.contextMenuAction(itemName, 'Restore');
  }

  async permanentlyDeleteItem(itemName: string) {
    await this.contextMenuAction(itemName, 'Delete Permanently');
    // Confirm in dialog
    await this.confirmButton.click();
  }

  async emptyBin() {
    await this.emptyBinButton.click();
    await this.confirmButton.click();
  }
}
```

