  1→/**
  2→ * BinBrowser -- Recycle bin browser with flat list of deleted items.
  3→ *
  4→ * Shows all soft-deleted files and folders in a flat list sorted by deletion date.
  5→ * Supports restore, permanent delete, batch operations, and Empty Bin.
  6→ * Auto-purges expired items on mount.
  7→ */
  8→
  9→import { useState, useCallback, useEffect, useRef, useMemo, type MouseEvent } from 'react';
 10→import type { BinEntry } from '@cipherbox/crypto';
 11→import { useBin } from '../../hooks/useBin';
 12→import { BinListItem } from './BinListItem';
 13→import { BinEmptyState } from './BinEmptyState';
 14→import { ConfirmDialog } from './ConfirmDialog';
 15→import '../../styles/bin-browser.css';
 16→
 17→type SortField = 'name' | 'deletedAt' | 'size' | 'daysRemaining';
 18→type SortDirection = 'asc' | 'desc';
 19→
 20→export function BinBrowser() {
 21→  const {
 22→    entries,
 23→    isLoading,
 24→    isLoaded,
 25→    error,
 26→    retentionDays,
 27→    daysRemaining,
 28→    loadBin,
 29→    restore,
 30→    permanentDelete,
 31→    emptyAll,
 32→    restoreMultiple,
 33→    permanentDeleteMultiple,
 34→    isLoading: isOperating,
 35→  } = useBin();
 36→
 37→  // Sort state
 38→  const [sortField, setSortField] = useState<SortField>('deletedAt');
 39→  const [sortDirection, setSortDirection] = useState<SortDirection>('desc');
 40→
 41→  // Selection state
 42→  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
 43→  const lastSelectedIdRef = useRef<string | null>(null);
 44→  const contextMenuRef = useRef<HTMLDivElement>(null);
 45→
 46→  // Confirmation dialog state
 47→  const [confirmDialog, setConfirmDialog] = useState<{
 48→    open: boolean;
 49→    title: string;
 50→    message: string;
 51→    confirmLabel: string;
 52→    onConfirm: () => void;
 53→  }>({ open: false, title: '', message: '', confirmLabel: '', onConfirm: () => {} });
 54→
 55→  // Context menu state
 56→  const [contextMenu, setContextMenu] = useState<{
 57→    visible: boolean;
 58→    x: number;
 59→    y: number;
 60→    entry: BinEntry | null;
 61→  }>({ visible: false, x: 0, y: 0, entry: null });
 62→
 63→  // Load bin on mount
 64→  useEffect(() => {
 65→    void loadBin();
 66→  }, [loadBin]);
 67→
 68→  // Prune stale selectedIds when entries change
 69→  const entryIds = useMemo(() => new Set(entries.map((e) => e.id)), [entries]);
 70→  useEffect(() => {
 71→    setSelectedIds((prev) => {
 72→      if (prev.size === 0) return prev;
 73→      const pruned = new Set([...prev].filter((id) => entryIds.has(id)));
 74→      if (pruned.size === prev.size) return prev;
 75→      return pruned;
 76→    });
 77→  }, [entryIds]);
 78→
 79→  // Sort entries
 80→  const sortedEntries = useMemo(() => {
 81→    const sorted = [...entries].sort((a, b) => {
 82→      let cmp = 0;
 83→      switch (sortField) {
 84→        case 'name':
 85→          cmp = a.name.localeCompare(b.name, undefined, { sensitivity: 'base' });
 86→          break;
 87→        case 'deletedAt':
 88→          cmp = a.deletedAt - b.deletedAt;
 89→          break;
 90→        case 'size':
 91→          cmp = a.size - b.size;
 92→          break;
 93→        case 'daysRemaining':
 94→          cmp = daysRemaining(a) - daysRemaining(b);
 95→          break;
 96→      }
 97→      return sortDirection === 'asc' ? cmp : -cmp;
 98→    });
 99→    return sorted;
100→  }, [entries, sortField, sortDirection, daysRemaining]);
101→
102→  // Toggle sort column
103→  const handleSortClick = useCallback(
104→    (field: SortField) => {
105→      if (sortField === field) {
106→        setSortDirection((prev) => (prev === 'asc' ? 'desc' : 'asc'));
107→      } else {
108→        setSortField(field);
109→        setSortDirection(field === 'name' ? 'asc' : 'desc');
110→      }
111→    },
112→    [sortField]
113→  );
114→
115→  // Sort indicator
116→  const sortIndicator = (field: SortField) => {
117→    if (sortField !== field) return '';
118→    return sortDirection === 'asc' ? ' ^' : ' v';
119→  };
120→
121→  // Selection handlers
122→  const handleSelect = useCallback(
123→    (entryId: string, event: { ctrlKey: boolean; shiftKey: boolean; metaKey: boolean }) => {
124→      const isCtrl = event.ctrlKey || event.metaKey;
125→      const isShift = event.shiftKey;
126→
127→      if (isShift && lastSelectedIdRef.current) {
128→        const ids = sortedEntries.map((e) => e.id);
129→        const startIdx = ids.indexOf(lastSelectedIdRef.current);
130→        const endIdx = ids.indexOf(entryId);
131→        if (startIdx !== -1 && endIdx !== -1) {
132→          const rangeStart = Math.min(startIdx, endIdx);
133→          const rangeEnd = Math.max(startIdx, endIdx);
134→          const rangeIds = ids.slice(rangeStart, rangeEnd + 1);
135→          setSelectedIds((prev) => {
136→            const next = new Set(prev);
137→            for (const id of rangeIds) next.add(id);
138→            return next;
139→          });
140→        }
141→      } else if (isCtrl) {
142→        setSelectedIds((prev) => {
143→          const next = new Set(prev);
144→          if (next.has(entryId)) next.delete(entryId);
145→          else next.add(entryId);
146→          return next;
147→        });
148→        lastSelectedIdRef.current = entryId;
149→      } else {
150→        setSelectedIds(new Set([entryId]));
151→        lastSelectedIdRef.current = entryId;
152→      }
153→    },
154→    [sortedEntries]
155→  );
156→
157→  const clearSelection = useCallback(() => {
158→    setSelectedIds(new Set());
159→    lastSelectedIdRef.current = null;
160→  }, []);
161→
162→  // Context menu handlers
163→  const handleContextMenu = useCallback(
164→    (event: MouseEvent, entry: BinEntry) => {
165→      event.preventDefault();
166→      // If right-clicked entry is not selected, select only that entry
167→      if (!selectedIds.has(entry.id)) {
168→        setSelectedIds(new Set([entry.id]));
169→        lastSelectedIdRef.current = entry.id;
170→      }
171→      setContextMenu({ visible: true, x: event.clientX, y: event.clientY, entry });
172→    },
173→    [selectedIds]
174→  );
175→
176→  const hideContextMenu = useCallback(() => {
177→    setContextMenu({ visible: false, x: 0, y: 0, entry: null });
178→  }, []);
179→
180→  // Close context menu on click outside or escape
181→  useEffect(() => {
182→    if (!contextMenu.visible) return;
183→
184→    const handleClickOutside = (event: globalThis.MouseEvent) => {
185→      if (contextMenuRef.current && !contextMenuRef.current.contains(event.target as Node)) {
186→        hideContextMenu();
187→      }
188→    };
189→    const handleKeyDown = (e: KeyboardEvent) => {
190→      if (e.key === 'Escape') hideContextMenu();
191→    };
192→
193→    document.addEventListener('mousedown', handleClickOutside, true);
194→    document.addEventListener('keydown', handleKeyDown);
195→    return () => {
196→      document.removeEventListener('mousedown', handleClickOutside, true);
197→      document.removeEventListener('keydown', handleKeyDown);
198→    };
199→  }, [contextMenu.visible, hideContextMenu]);
200→
201→  // Action handlers
202→  const handleRestore = useCallback(
203→    async (entryId: string) => {
204→      try {
205→        await restore(entryId);
206→        clearSelection();
207→      } catch (err) {
208→        console.error('Restore failed:', err);
209→      }
210→    },
211→    [restore, clearSelection]
212→  );
213→
214→  const handlePermanentDelete = useCallback(
215→    (entryId: string) => {
216→      const entry = entries.find((e) => e.id === entryId);
217→      const name = entry?.name ?? 'this item';
218→      setConfirmDialog({
219→        open: true,
220→        title: 'Delete Permanently?',
221→        message: `This will permanently delete "${name}". This cannot be undone.`,
222→        confirmLabel: 'Delete Permanently',
223→        onConfirm: async () => {
224→          try {
225→            await permanentDelete(entryId);
226→            clearSelection();
227→            setConfirmDialog((prev) => ({ ...prev, open: false }));
228→          } catch (err) {
229→            console.error('Permanent delete failed:', err);
230→          }
231→        },
232→      });
233→    },
234→    [entries, permanentDelete, clearSelection]
235→  );
236→
237→  // Context menu actions
238→  const handleContextRestore = useCallback(() => {
239→    if (!contextMenu.entry) return;
240→    hideContextMenu();
241→    void handleRestore(contextMenu.entry.id);
242→  }, [contextMenu.entry, hideContextMenu, handleRestore]);
243→
244→  const handleContextPermanentDelete = useCallback(() => {
245→    if (!contextMenu.entry) return;
246→    hideContextMenu();
247→    handlePermanentDelete(contextMenu.entry.id);
248→  }, [contextMenu.entry, hideContextMenu, handlePermanentDelete]);
249→
250→  // Batch actions
251→  const handleBatchRestore = useCallback(async () => {
252→    if (selectedIds.size === 0) return;
253→    try {
254→      await restoreMultiple([...selectedIds]);
255→      clearSelection();
256→    } catch (err) {
257→      console.error('Batch restore failed:', err);
258→    }
259→  }, [selectedIds, restoreMultiple, clearSelection]);
260→
261→  const handleBatchPermanentDelete = useCallback(() => {
262→    if (selectedIds.size === 0) return;
263→    const count = selectedIds.size;
264→    setConfirmDialog({
265→      open: true,
266→      title: `Delete ${count} Items Permanently?`,
267→      message: `This will permanently delete ${count} selected item${count !== 1 ? 's' : ''}. This cannot be undone.`,
268→      confirmLabel: 'Delete Permanently',
269→      onConfirm: async () => {
270→        try {
271→          await permanentDeleteMultiple([...selectedIds]);
272→          clearSelection();
273→          setConfirmDialog((prev) => ({ ...prev, open: false }));
274→        } catch (err) {
275→          console.error('Batch permanent delete failed:', err);
276→        }
277→      },
278→    });
279→  }, [selectedIds, permanentDeleteMultiple, clearSelection]);
280→
281→  // Empty Bin
282→  const handleEmptyBin = useCallback(() => {
283→    const count = entries.length;
284→    setConfirmDialog({
285→      open: true,
286→      title: 'Empty Bin?',
287→      message: `This will permanently delete all ${count} item${count !== 1 ? 's' : ''} in the bin. This cannot be undone.`,
288→      confirmLabel: 'Empty Bin',
289→      onConfirm: async () => {
290→        try {
291→          await emptyAll();
292→          clearSelection();
293→          setConfirmDialog((prev) => ({ ...prev, open: false }));
294→        } catch (err) {
295→          console.error('Empty bin failed:', err);
296→        }
297→      },
298→    });
299→  }, [entries.length, emptyAll, clearSelection]);
300→
301→  const closeConfirmDialog = useCallback(() => {
302→    setConfirmDialog((prev) => ({ ...prev, open: false }));
303→  }, []);
304→
305→  const hasEntries = entries.length > 0;
306→  const multiSelectActive = selectedIds.size > 1;
307→
308→  return (
309→    <div className="file-browser-content bin-browser">
310→      {/* Toolbar with title and Empty Bin */}
311→      <div className="file-browser-toolbar">
312→        <nav className="breadcrumb-nav" aria-label="Current location" data-testid="breadcrumbs">
313→          <span className="breadcrumb-prefix">~</span>
314→          <span className="breadcrumb-separator">/</span>
315→          <span className="breadcrumb-item breadcrumb-item--current" aria-current="page">
316→            bin
317→          </span>
318→        </nav>
319→        <div className="file-browser-actions">
320→          {hasEntries && (
321→            <button
322→              type="button"
323→              className="toolbar-btn toolbar-btn--destructive"
324→              onClick={handleEmptyBin}
325→              disabled={isOperating}
326→              aria-label="Empty bin"
327→              data-testid="empty-bin-btn"
328→            >
329→              {'// empty bin'}
330→            </button>
331→          )}
332→        </div>
333→      </div>
334→
335→      {/* Error state */}
336→      {error && (
337→        <div className="bin-error" role="alert">
338→          <span>
339→            {'// ERROR: '}
340→            {error}
341→          </span>
342→        </div>
343→      )}
344→
345→      {/* Loading state */}
346→      {isLoading && !isLoaded && (
347→        <div className="file-browser-loading">
348→          <span className="file-browser-loading-spinner">{'// loading bin...'}</span>
349→        </div>
350→      )}
351→
352→      {/* Bin items list */}
353→      {isLoaded && hasEntries && (
354→        <div className="file-list bin-list" role="grid" data-testid="bin-list">
355→          {/* Column headers */}
356→          <div className="file-list-header bin-list-header" role="row">
357→            <button
358→              type="button"
359→              className="bin-column-header bin-column-name"
360→              onClick={() => handleSortClick('name')}
361→              role="columnheader"
362→              aria-sort={
363→                sortField === 'name'
364→                  ? sortDirection === 'asc'
365→                    ? 'ascending'
366→                    : 'descending'
367→                  : 'none'
368→              }
369→            >
370→              {'[NAME]'}
371→              {sortIndicator('name')}
372→            </button>
373→            <div className="bin-column-header bin-column-path" role="columnheader">
374→              [LOCATION]
375→            </div>
376→            <button
377→              type="button"
378→              className="bin-column-header bin-column-deleted"
379→              onClick={() => handleSortClick('deletedAt')}
380→              role="columnheader"
381→              aria-sort={
382→                sortField === 'deletedAt'
383→                  ? sortDirection === 'asc'
384→                    ? 'ascending'
385→                    : 'descending'
386→                  : 'none'
387→              }
388→            >
389→              {'[DELETED]'}
390→              {sortIndicator('deletedAt')}
391→            </button>
392→            <button
393→              type="button"
394→              className="bin-column-header bin-column-size"
395→              onClick={() => handleSortClick('size')}
396→              role="columnheader"
397→              aria-sort={
398→                sortField === 'size'
399→                  ? sortDirection === 'asc'
400→                    ? 'ascending'
401→                    : 'descending'
402→                  : 'none'
403→              }
404→            >
405→              {'[SIZE]'}
406→              {sortIndicator('size')}
407→            </button>
408→            <button
409→              type="button"
410→              className="bin-column-header bin-column-remaining"
411→              onClick={() => handleSortClick('daysRemaining')}
412→              role="columnheader"
413→              aria-sort={
414→                sortField === 'daysRemaining'
415→                  ? sortDirection === 'asc'
416→                    ? 'ascending'
417→                    : 'descending'
418→                  : 'none'
419→              }
420→            >
421→              {'[TIME LEFT]'}
422→              {sortIndicator('daysRemaining')}
423→            </button>
424→          </div>
425→
426→          {/* Item rows */}
427→          <div className="file-list-body" role="rowgroup">
428→            {sortedEntries.map((entry) => (
429→              <BinListItem
430→                key={entry.id}
431→                entry={entry}
432→                isSelected={selectedIds.has(entry.id)}
433→                daysLeft={daysRemaining(entry)}
434→                onSelect={handleSelect}
435→                onContextMenu={handleContextMenu}
436→              />
437→            ))}
438→          </div>
439→        </div>
440→      )}
441→
442→      {/* Empty state */}
443→      {isLoaded && !hasEntries && <BinEmptyState retentionDays={retentionDays} />}
444→
445→      {/* Selection action bar */}
446→      {multiSelectActive && (
447→        <div
448→          className="selection-action-bar bin-selection-bar"
449→          role="toolbar"
450→          aria-label="Bin selection actions"
451→        >
452→          <div className="selection-action-bar-info">
453→            <span className="selection-action-bar-count">
454→              {selectedIds.size} item{selectedIds.size !== 1 ? 's' : ''} selected
455→            </span>
456→            <button
457→              type="button"
458→              className="selection-action-bar-clear"
459→              onClick={clearSelection}
460→              aria-label="Clear selection"
461→            >
462→              [clear]
463→            </button>
464→          </div>
465→          <div className="selection-action-bar-actions">
466→            <button
467→              type="button"
468→              className="toolbar-btn toolbar-btn--secondary"
469→              onClick={handleBatchRestore}
470→              disabled={isOperating}
471→              aria-label={`Restore ${selectedIds.size} items`}
472→            >
473→              {'<- restore'}
474→            </button>
475→            <button
476→              type="button"
477→              className="toolbar-btn toolbar-btn--secondary selection-action-bar-delete"
478→              onClick={handleBatchPermanentDelete}
479→              disabled={isOperating}
480→              aria-label={`Delete ${selectedIds.size} items permanently`}
481→            >
482→              {'x delete permanently'}
483→            </button>
484→          </div>
485→        </div>
486→      )}
487→
488→      {/* Context menu */}
489→      {contextMenu.visible && contextMenu.entry && (
490→        <div
491→          ref={contextMenuRef}
492→          className="context-menu bin-context-menu"
493→          style={{ position: 'fixed', left: contextMenu.x, top: contextMenu.y }}
494→          role="menu"
495→          aria-label={`Actions for ${contextMenu.entry.name}`}
496→          data-testid="bin-context-menu"
497→        >
498→          <button
499→            type="button"
500→            className="context-menu-item"
501→            onClick={handleContextRestore}
502→            role="menuitem"
503→          >
504→            <span className="context-menu-item-icon">{'<-'}</span>
505→            Restore
506→          </button>
507→          <div className="context-menu-divider" role="separator" />
508→          <button
509→            type="button"
510→            className="context-menu-item context-menu-item--destructive"
511→            onClick={handleContextPermanentDelete}
512→            role="menuitem"
513→          >
514→            <span className="context-menu-item-icon">&#128465;</span>
515→            Delete Permanently
516→          </button>
517→        </div>
518→      )}
519→
520→      {/* Confirmation dialog */}
521→      <ConfirmDialog
522→        open={confirmDialog.open}
523→        onClose={closeConfirmDialog}
524→        onConfirm={confirmDialog.onConfirm}
525→        title={confirmDialog.title}
526→        message={confirmDialog.message}
527→        confirmLabel={confirmDialog.confirmLabel}
528→        isDestructive
529→        isLoading={isOperating}
530→      />
531→    </div>
532→  );
533→}
