108→
109→  /**
110→   * Check if vault exists for user (returns null if not)
111→   */
112→  async findVault(userId: string): Promise<VaultResponseDto | null> {
113→    const vault = await this.vaultRepository.findOne({
114→      where: { ownerId: userId },
115→    });
116→
117→    if (!vault) return null;
118→
119→    const teeKeys = await this.teeKeyStateService.getTeeKeysDto();
120→    return this.toVaultResponse(vault, teeKeys);
121→  }
122→
123→  /**
124→   * Get current storage quota usage for a user
125→   */
126→  async getQuota(userId: string): Promise<QuotaResponseDto> {
127→    const result = await this.pinnedCidRepository
128→      .createQueryBuilder('pin')
129→      .select('COALESCE(SUM(pin.size_bytes), 0)', 'total')
130→      .where('pin.user_id = :userId', { userId })
131→      .getRawOne<{ total: string }>();
132→
133→    const usedBytes = parseInt(result?.total ?? '0', 10);
134→    const remainingBytes = Math.max(0, QUOTA_LIMIT_BYTES - usedBytes);
135→
136→    return {
137→      usedBytes,
138→      limitBytes: QUOTA_LIMIT_BYTES,
139→      remainingBytes,
140→    };
141→  }
142→
143→  /**
144→   * Check if user has sufficient quota for additional storage
145→   *
146→   * @returns true if (current usage + additionalBytes) <= quota limit
147→   */
148→  async checkQuota(userId: string, additionalBytes: number): Promise<boolean> {
149→    const quota = await this.getQuota(userId);
150→    return quota.usedBytes + additionalBytes <= QUOTA_LIMIT_BYTES;
151→  }
152→
153→  /**
154→   * Record a pinned CID for quota tracking
155→   * Uses upsert (ON CONFLICT DO NOTHING) for idempotency
156→   */
157→  async recordPin(userId: string, cid: string, sizeBytes: number): Promise<void> {
158→    await this.pinnedCidRepository
159→      .createQueryBuilder()
160→      .insert()
161→      .into(PinnedCid)
162→      .values({
163→        userId,
164→        cid,
165→        sizeBytes: sizeBytes.toString(),
166→      })
167→      .orIgnore() // ON CONFLICT DO NOTHING for idempotency
168→      .execute();
169→  }
170→
171→  /**
172→   * Remove a pinned CID record
173→   * Idempotent - no error if CID not found
174→   */
175→  async recordUnpin(userId: string, cid: string): Promise<void> {
176→    await this.pinnedCidRepository.delete({
177→      userId,
178→      cid,
179→    });
180→  }
181→
182→  /**
183→   * Mark vault as initialized (first file uploaded)
184→   */
185→  async markInitialized(userId: string): Promise<void> {
186→    await this.vaultRepository.update({ ownerId: userId }, { initializedAt: new Date() });
187→  }
188→
189→  /**
190→   * Get export data for independent recovery.
191→   * Returns the minimal set of fields needed to reconstruct the vault:
192→   * root IPNS name + encrypted root keys + derivation hints.
193→   */
194→  async getExportData(userId: string): Promise<VaultExportDto> {
195→    const vault = await this.vaultRepository.findOne({
196→      where: { ownerId: userId },
197→    });
198→
199→    if (!vault) {
200→      throw new NotFoundException('Vault not found');
201→    }
202→
203→    const user = await this.userRepository.findOne({
204→      where: { id: userId },
205→    });
206→
207→    return {
208→      format: 'cipherbox-vault-export',
209→      version: '1.0',
210→      exportedAt: new Date().toISOString(),
211→      rootIpnsName: vault.rootIpnsName,
212→      encryptedRootFolderKey: vault.encryptedRootFolderKey.toString('hex'),
213→      encryptedRootIpnsPrivateKey: vault.encryptedRootIpnsPrivateKey.toString('hex'),
214→      derivationMethod: user ? 'web3auth' : null,
215→    };
216→  }
217→
218→  /**
219→   * Convert Vault entity to response DTO with hex-encoded fields
220→   */
221→  private toVaultResponse(vault: Vault, teeKeys: TeeKeysDto | null = null): VaultResponseDto {
222→    return {
223→      id: vault.id,
224→      ownerPublicKey: vault.ownerPublicKey.toString('hex'),
225→      encryptedRootFolderKey: vault.encryptedRootFolderKey.toString('hex'),
226→      encryptedRootIpnsPrivateKey: vault.encryptedRootIpnsPrivateKey.toString('hex'),
227→      rootIpnsName: vault.rootIpnsName,
228→      createdAt: vault.createdAt,
229→      initializedAt: vault.initializedAt,
230→      teeKeys,
231→    };
232→  }
233→}
