    id: `entry-${i}-${crypto.randomUUID()}`,
    itemType: i % 2 === 0 ? ('file' as const) : ('folder' as const),
    name: `test-item-${i}.txt`,
    originalParentIpnsName: `k51${'a'.repeat(59)}`,
