            itemType: 'file',
            name: 'test.txt',
            originalParentIpnsName: 'k51xxx',
            originalPath: '/test.txt',
            deletedAt: Date.now(),
            size: 100,
            mimeType: 'text/plain',
          },
        ],
      })
    ).toThrow('Invalid bin metadata format');
  });

  it('rejects entry with invalid itemType', () => {
    expect(() =>
      validateBinMetadata({
        version: 'v1',
        sequenceNumber: 1,
        entries: [
          {
            id: 'abc',
            itemType: 'symlink',
            name: 'test.txt',
            originalParentIpnsName: 'k51xxx',
            originalPath: '/test.txt',
            deletedAt: Date.now(),
            size: 100,
            mimeType: 'text/plain',
          },
        ],
      })
    ).toThrow('Invalid bin metadata format');
  });

  it('rejects entry with non-string name', () => {
    expect(() =>
      validateBinMetadata({
        version: 'v1',
        sequenceNumber: 1,
        entries: [
          {
            id: 'abc',
            itemType: 'file',
            name: 123,
            originalParentIpnsName: 'k51xxx',
            originalPath: '/test.txt',
            deletedAt: Date.now(),
            size: 100,
            mimeType: 'text/plain',
          },
        ],
      })
    ).toThrow('Invalid bin metadata format');
  });

  it('rejects entry with non-string originalParentIpnsName', () => {
    expect(() =>
      validateBinMetadata({
        version: 'v1',
        sequenceNumber: 1,
        entries: [
          {
            id: 'abc',
            itemType: 'file',
            name: 'test.txt',
            originalParentIpnsName: 42,
            originalPath: '/test.txt',
            deletedAt: Date.now(),
            size: 100,
            mimeType: 'text/plain',
          },
        ],
      })
    ).toThrow('Invalid bin metadata format');
  });

  it('rejects entry with non-string originalPath', () => {
    expect(() =>
      validateBinMetadata({
        version: 'v1',
        sequenceNumber: 1,
        entries: [
          {
            id: 'abc',
            itemType: 'file',
            name: 'test.txt',
            originalParentIpnsName: 'k51xxx',
            originalPath: null,
            deletedAt: Date.now(),
            size: 100,
            mimeType: 'text/plain',
          },
        ],
      })
    ).toThrow('Invalid bin metadata format');
  });

  it('rejects entry with non-number deletedAt', () => {
    expect(() =>
      validateBinMetadata({
        version: 'v1',
        sequenceNumber: 1,
        entries: [
          {
            id: 'abc',
            itemType: 'file',
            name: 'test.txt',
            originalParentIpnsName: 'k51xxx',
            originalPath: '/test.txt',
            deletedAt: '2026-01-01',
            size: 100,
            mimeType: 'text/plain',
          },
        ],
      })
    ).toThrow('Invalid bin metadata format');
  });

  it('rejects entry with negative size', () => {
    expect(() =>
      validateBinMetadata({
        version: 'v1',
        sequenceNumber: 1,
        entries: [
          {
            id: 'abc',
            itemType: 'file',
            name: 'test.txt',
            originalParentIpnsName: 'k51xxx',
            originalPath: '/test.txt',
            deletedAt: Date.now(),
            size: -1,
            mimeType: 'text/plain',
          },
        ],
      })
    ).toThrow('Invalid bin metadata format');
  });

  it('rejects entry with non-string mimeType', () => {
    expect(() =>
      validateBinMetadata({
        version: 'v1',
        sequenceNumber: 1,
        entries: [
          {
            id: 'abc',
            itemType: 'file',
            name: 'test.txt',
            originalParentIpnsName: 'k51xxx',
            originalPath: '/test.txt',
            deletedAt: Date.now(),
            size: 100,
            mimeType: null,
          },
        ],
      })
    ).toThrow('Invalid bin metadata format');
  });

  it('rejects entry with non-object filePointer', () => {
    expect(() =>
      validateBinMetadata({
        version: 'v1',
        sequenceNumber: 1,
        entries: [
          {
            id: 'abc',
            itemType: 'file',
            name: 'test.txt',
            originalParentIpnsName: 'k51xxx',
            originalPath: '/test.txt',
            deletedAt: Date.now(),
            size: 100,
            mimeType: 'text/plain',
            filePointer: 'not-an-object',
          },
        ],
      })
    ).toThrow('Invalid bin metadata format');
  });

  it('rejects entry with non-object folderEntry', () => {
    expect(() =>
      validateBinMetadata({
        version: 'v1',
        sequenceNumber: 1,
        entries: [
          {
            id: 'abc',
            itemType: 'folder',
            name: 'docs',
            originalParentIpnsName: 'k51xxx',
            originalPath: '/docs',
            deletedAt: Date.now(),
            size: 0,
            mimeType: '',
            folderEntry: 'not-an-object',
          },
        ],
      })
    ).toThrow('Invalid bin metadata format');
  });

  it('accepts entry with null filePointer (treated as undefined)', () => {
    // null filePointer should fail since it's not undefined and not a non-null object
    expect(() =>
      validateBinMetadata({
        version: 'v1',
        sequenceNumber: 1,
        entries: [
          {
            id: 'abc',
            itemType: 'file',
            name: 'test.txt',
            originalParentIpnsName: 'k51xxx',
            originalPath: '/test.txt',
            deletedAt: Date.now(),
            size: 100,
            mimeType: 'text/plain',
            filePointer: null,
          },
        ],
      })
    ).toThrow('Invalid bin metadata format');
  });

  it('rejects entry that is not an object', () => {
    expect(() =>
      validateBinMetadata({
        version: 'v1',
        sequenceNumber: 1,
        entries: ['not-an-entry'],
      })
    ).toThrow('Invalid bin metadata format');
  });

  it('rejects entry that is null', () => {
    expect(() =>
      validateBinMetadata({
        version: 'v1',
        sequenceNumber: 1,
        entries: [null],
      })
    ).toThrow('Invalid bin metadata format');
  });
});

