import { useCallback, type MouseEvent } from 'react';
import type { BinEntry } from '@cipherbox/crypto';
import { formatBytes } from '../../utils/format';

type BinListItemProps = {
  /** The bin entry to display */
  entry: BinEntry;
  /** Whether this item is currently selected */
  isSelected: boolean;
  /** Days remaining before auto-purge */
  daysLeft: number;
  /** Callback when item is clicked (with modifier key info) */
  onSelect: (
    entryId: string,
    event: { ctrlKey: boolean; shiftKey: boolean; metaKey: boolean }
  ) => void;
  /** Callback when right-click context menu is requested */
  onContextMenu: (event: MouseEvent, entry: BinEntry) => void;
};

/**
 * Format a deletion timestamp as a relative time string.
 */
function formatRelativeTime(timestamp: number): string {
  const diff = Date.now() - timestamp;
  const seconds = Math.floor(diff / 1000);
  const minutes = Math.floor(seconds / 60);
  const hours = Math.floor(minutes / 60);
  const days = Math.floor(hours / 24);

  if (seconds < 60) return 'just now';
  if (minutes < 60) return `${minutes}m ago`;
  if (hours < 24) return `${hours}h ago`;
  if (days === 1) return '1 day ago';
  return `${days} days ago`;
}

/**
 * Get a terminal-style type indicator based on item type and MIME.
 */
function getItemIcon(entry: BinEntry): string {
  if (entry.itemType === 'folder') return '[DIR]';
  if (!entry.mimeType) return '[FILE]';
  if (entry.mimeType.startsWith('image/')) return '[IMG]';
  if (entry.mimeType.startsWith('video/')) return '[VID]';
  if (entry.mimeType.startsWith('audio/')) return '[AUD]';
  if (entry.mimeType.startsWith('text/')) return '[TXT]';
  if (entry.mimeType === 'application/pdf') return '[PDF]';
  return '[FILE]';
}

/**
 * Single row in the bin list.
 *
 * Displays deleted item with name, original location, deletion date,
 * file size, and days remaining before auto-purge.
 */
export function BinListItem({
  entry,
  isSelected,
  daysLeft,
  onSelect,
  onContextMenu,
}: BinListItemProps) {
  const handleClick = useCallback(
    (e: React.MouseEvent) => {
      onSelect(entry.id, { ctrlKey: e.ctrlKey, shiftKey: e.shiftKey, metaKey: e.metaKey });
    },
    [entry.id, onSelect]
  );

  const handleCheckboxClick = useCallback(
    (e: React.MouseEvent) => {
      e.stopPropagation();
      onSelect(entry.id, { ctrlKey: true, shiftKey: false, metaKey: false });
    },
    [entry.id, onSelect]
  );

  const handleContextMenu = useCallback(
    (e: MouseEvent) => {
      e.preventDefault();
      onContextMenu(e, entry);
    },
    [entry, onContextMenu]
  );

  const sizeDisplay =
    entry.itemType === 'folder' && entry.size === 0 ? 'Folder' : formatBytes(entry.size);

  const remainingText = daysLeft <= 0 ? 'expired' : daysLeft === 1 ? '< 1 day' : `${daysLeft}d`;

  const isWarning = daysLeft <= 3;

  const className = [
    'bin-list-item',
    isSelected ? 'bin-list-item--selected' : '',
    isWarning ? 'bin-list-item--warning' : '',
  ]
    .filter(Boolean)
    .join(' ');

  return (
    <div
      className={className}
      data-testid={`bin-item-${entry.id}`}
      onClick={handleClick}
      onContextMenu={handleContextMenu}
      role="row"
      aria-selected={isSelected}
      tabIndex={0}
      onKeyDown={(e) => {
        if (e.key === 'Enter') {
          e.preventDefault();
          onContextMenu(e as unknown as MouseEvent, entry);
        }
      }}
    >
      <div className="bin-list-item-name" role="gridcell">
        <span
          className="bin-list-item-checkbox"
          onClick={handleCheckboxClick}
          role="checkbox"
          aria-checked={isSelected}
          aria-label={`Select ${entry.name}`}
          tabIndex={-1}
          onKeyDown={(e) => {
            if (e.key === 'Enter' || e.key === ' ') {
              e.preventDefault();
              e.stopPropagation();
              onSelect(entry.id, { ctrlKey: true, shiftKey: false, metaKey: false });
            }
          }}
        >
          {isSelected ? '[x]' : '[ ]'}
        </span>
        <span className="bin-list-item-icon" aria-hidden="true">
          {getItemIcon(entry)}
        </span>
        <span className="bin-list-item-label">{entry.name}</span>
      </div>
      <div className="bin-list-item-path" role="gridcell" title={entry.originalPath}>
        {entry.originalPath}
      </div>
      <div className="bin-list-item-deleted" role="gridcell">
        {formatRelativeTime(entry.deletedAt)}
      </div>
      <div className="bin-list-item-size" role="gridcell">
        {sizeDisplay}
      </div>
      <div
        className={`bin-list-item-remaining ${isWarning ? 'bin-list-item-remaining--warning' : ''}`}
        role="gridcell"
      >
        {remainingText}
      </div>
    </div>
  );
}

# test-recycle-bin.ps1 -- Verify FUSE deletes create recoverable bin entries (Windows).
#
# Usage: .\test-recycle-bin.ps1 [-MountPoint <path>] [-ApiUrl <url>]
#   -MountPoint   Path to FUSE mount (default: $env:USERPROFILE\CipherBox)
#   -ApiUrl       Backend API URL (default: http://localhost:3000)
#
# Environment:
#   TEST_SECRET   test-login shared secret (default: e2e-test-secret-ci-only)
#
# Tests:
#   1. Create test file on FUSE mount
#   2. Delete file, verify gone from mount
#   3. Verify API reachable with auth (vault config accessible)
#   4. Verify file CID preserved (soft-delete behavior)
#
# Exit code: number of failed tests (0 = all passed).

param(
    [string]$MountPoint = "$env:USERPROFILE\CipherBox",
    [string]$ApiUrl = "http://localhost:3000"
)

$TestSecret = if ($env:TEST_SECRET) { $env:TEST_SECRET } else { "e2e-test-secret-ci-only" }

$ErrorActionPreference = "Continue"

$TestEmail = "dev-key@cipherbox.local"

$Pass = 0
$Fail = 0

function Test-Pass {
    param([string]$Name)
    $script:Pass++
    Write-Host "PASS: $Name"
}

function Test-Fail {
    param([string]$Name)
    $script:Fail++
    Write-Host "FAIL: $Name"
}

Write-Host "=== Recycle Bin E2E Tests ==="
Write-Host "Mount point: $MountPoint"
Write-Host "API URL:     $ApiUrl"
Write-Host "Test email:  $TestEmail"
Write-Host ""

# ---- Setup: Authenticate via test-login ----
Write-Host "--- Setup: Authenticate via test-login ---"
$Body = @{
    email  = $TestEmail
    secret = $TestSecret
} | ConvertTo-Json

$AccessToken = $null
try {
    $AuthResponse = Invoke-RestMethod -Uri "$ApiUrl/auth/test-login" `
        -Method Post `
        -ContentType "application/json" `
        -Body $Body

    $AccessToken = $AuthResponse.accessToken
    if (-not $AccessToken) {
        throw "No accessToken in response"
    }
    Write-Host "Authenticated OK"
} catch {
    Write-Host "FATAL: Could not get auth token ($_). Is the API running?"
    Write-Host ""
    Write-Host "=== Recycle Bin E2E Results ==="
    Write-Host "  Passed: $Pass"
    Write-Host "  Failed: $Fail"
    Write-Host "==============================="
    exit 1
}

$Headers = @{ Authorization = "Bearer $AccessToken" }
Write-Host ""

# ---- Test 1: Create test file on mount ----
$TestFile = "e2e-bin-$(Get-Random).txt"
Write-Host "--- Test 1: Create test file ($TestFile) ---"
$TestContent = "Bin test content $(Get-Date -UFormat %s)"
try {
    Set-Content -Path "$MountPoint\$TestFile" -Value $TestContent -NoNewline -ErrorAction Stop
    Start-Sleep -Seconds 10  # Wait for upload + IPNS publish

    if (Test-Path "$MountPoint\$TestFile") {
        Test-Pass "Create test file"
    } else {
        Test-Fail "Create test file (not found after write)"
    }
} catch {
    Test-Fail "Create test file ($_)"
}

# Capture pre-deletion content
$PreDeleteContent = ""
try {
    $PreDeleteContent = Get-Content -Path "$MountPoint\$TestFile" -Raw -ErrorAction SilentlyContinue
} catch { }

# ---- Test 2: Delete file from mount ----
Write-Host "--- Test 2: Delete file from mount ---"
try {
    Remove-Item -Path "$MountPoint\$TestFile" -Force -ErrorAction Stop
    Start-Sleep -Seconds 10  # Wait for folder metadata publish + bin IPNS publish

    if (-not (Test-Path "$MountPoint\$TestFile")) {
        Test-Pass "Delete file from mount (file removed)"
    } else {
        Test-Fail "Delete file from mount (file still exists)"
    }
} catch {
    Test-Fail "Delete file from mount ($_)"
}

# ---- Test 3: Verify vault config reachable (API health for bin) ----
Write-Host "--- Test 3: Verify vault config reachable ---"
try {
    $VaultResponse = Invoke-RestMethod -Uri "$ApiUrl/vault" -Headers $Headers
    if ($VaultResponse) {
        Test-Pass "Vault API reachable (bin entries stored server-side)"
    } else {
        Test-Fail "Vault API returned empty response"
    }
} catch {
    Test-Fail "Vault API unreachable ($_)"
}

# ---- Test 4: Verify soft-delete behavior ----
Write-Host "--- Test 4: Verify soft-delete behavior ---"
$FileGone = -not (Test-Path "$MountPoint\$TestFile")
$HadContent = $PreDeleteContent.Length -gt 0

if ($FileGone -and $HadContent) {
    Test-Pass "Soft-delete behavior (file removed from mount, had content before deletion)"
} elseif (-not $HadContent) {
    Test-Fail "Soft-delete behavior (file had no content before deletion)"
} else {
    Test-Fail "Soft-delete behavior (file still on mount after deletion)"
}

# ---- Cleanup ----
Write-Host "--- Cleanup ---"
Remove-Item -Path "$MountPoint\$TestFile" -Force -ErrorAction SilentlyContinue
Test-Pass "Cleanup"

# ---- Summary ----
Write-Host ""
Write-Host "=== Recycle Bin E2E Results ==="
Write-Host "  Passed: $Pass"
Write-Host "  Failed: $Fail"
Write-Host "==============================="

exit $Fail

